        "heading": "濠梁之辩——庄子与惠施的哲学论战",
        "body": "庄子与惠施游于濠梁之上。庄子曰：「鯈鱼出游从容，是鱼之乐也。」惠施曰：「子非鱼，安知鱼之乐？」庄子曰：「子非我，安知我不知鱼之乐？」惠施曰：「我非子，固不知子矣；子固非鱼也，子之不知鱼之乐，全矣！」庄子曰：「请循其本。子曰『汝安知鱼乐』云者，既已知吾知之而问我，我知之濠上也。」这场辩论是中国哲学史上关于「认识论」最精彩的对话。"
