    "sections": [
      {
        "type": "paragraph",
        "heading": "生平：从贫民到「素王」的传奇",
        "body": "孔子 3 岁时父亲孔纥去世，家道中落。少年时做过仓库管理员（委吏）、牧场管理员（乘田）。他自己说「吾少也贱，故多能鄙事」。50 岁时因政绩被鲁定公任命为中都宰（首都市长），仅一年便升为大司寇（最高司法官）兼摄相事。公元前 497 年因与执政者季氏不合，55 岁起周游列国 14 年，先后到卫、陈、蔡、楚等国推销仁政，未被采纳。68 岁返鲁，专整理典籍与教学，73 岁去世。"
      },
      {
        "type": "callout",
        "heading": "核心思想：仁 · 礼 · 中庸",
        "body": "「仁」是孔子伦理学的最高范畴——爱人。樊迟问仁，子曰「爱人」。仁的实践路径是「克己复礼为仁」，「己所不欲，勿施于人」是仁的黄金法则。「中庸」是儒家方法论——无过无不及，恰到好处。「礼」是社会规范——克己复礼，礼乐教化。",
        "variant": "info"
      },
      {
        "type": "quote",
        "text": "**己所不欲，勿施于人**。",
        "cite": "《论语·颜渊》"
      },
      {
        "type": "quote",
        "text": "**三人行，必有我师焉。择其善者而从之，其不善者而改之**。",
        "cite": "《论语·述而》"
      },
      {
        "type": "quote",
        "text": "**学而不思则罔，思而不学则殆**。",
        "cite": "《论语·为政》"
      },
      {
        "type": "quote",
        "text": "**知之为知之，不知为不知，是知也**。",
        "cite": "《论语·为政》"
      },
      {
        "type": "paragraph",
        "heading": "整理五经——中华文明的奠基工程",
        "body": "孔子晚年整理了六经（《诗》《书》《礼》《易》《乐》《春秋》），其中《乐》失传，成为「五经」。这些典籍原是周代贵族教育的教材，经孔子整理修订，成为中华文明的源头活水。从汉代起，五经成为历代科举考试的核心。至今两岸四地的孩子仍要背诵《诗经》《论语》。"
      },
      {
        "type": "paragraph",
        "heading": "周游列国——理想主义的 14 年流浪",
        "body": "公元前 497 年至公元前 484 年，55 岁的孔子率弟子周游列国，先后到卫国、陈国、蔡国、楚国等推销「仁政」理想。然而当时诸侯忙于争霸，无人采纳。在陈蔡之间甚至被围困，断粮七日，弟子子路抱怨，孔子讲诵礼乐不绝。返鲁后他说：「如有用我者，吾其为东周乎？」"
      },
      {
        "type": "list",
        "heading": "孔子生平大事年表",
        "items": [
          "BC 551：生于鲁国陬邑",
          "BC 533：3岁丧父",
          "BC 534：17岁丧母",
          "BC 525：任委吏（仓库管理员）",
          "BC 518：任乘田（牧场管理员）",
          "BC 517：赴周问礼于老子（**孔子问礼**）",
          "BC 501：任中都宰",
          "BC 500：升司空、大司寇",
          "BC 497：周游列国开始",
          "BC 484：返鲁",
          "BC 479：73岁去世"
        ]
      },
      {
        "type": "paragraph",
        "heading": "对世界的深远影响",
        "body": "儒家思想是东亚文明圈的根基。朝鲜半岛、越南、日本琉球历史上皆尊儒。法国启蒙思想家伏尔泰说：「我读孔子的书，发现里面只有最纯粹的道德，而没有一句谎言。」美国最高法院东门镌刻「Equal Justice Under Law」，背后就是儒家「义」的理念。孔子学院遍布全球 160+ 国家，孔子被誉为「世界十大文化名人之首」。"
      }
    ],
