      {
        "type": "paragraph",
        "heading": "对世界的深远影响",
        "body": "苏格拉底之死是西方哲学的奠基性事件。他以身作则证明了「良心高于法律」「真理高于生命」「理性高于习俗」，这成为西方知识分子的精神基因。康德的「启蒙」定义——敢于运用你自己的理性——直接呼应苏格拉底。20 世纪存在主义哲学家（如加缪）都从苏格拉底之死中获得灵感。黑格尔说：「苏格拉底的命运是哲学史上最重要的事件之一。」"
      }
