    "title": "儒家亚圣，性善论集大成者",
    "summary": "战国中期邹国（今山东邹城）人，名轲，字子舆。孔子之孙子思的学生。曾游说齐宣王、梁惠王等推行仁政，未被采纳。晚年与弟子万章、公孙丑等著《孟子》七篇。",
