        "heading": "生平：工匠出身的哲学大师",
        "body": "墨子出身底层，做过工匠。精通木工、机械。墨子游说诸侯，曾用守城器械帮宋国守城，迫使楚国退兵。他反对儒家繁琐的礼乐，主张「兼爱」「非攻」。"
