    "summary": "法国哲学家、数学家。父亲是布列塔尼地方议员。8 岁入拉弗莱什学院。1616 年毕业于普瓦捷大学法律系。1618 年参军，1619 年冬天在德国军营里梦见「新哲学的奇迹」。1628 年移居荷兰专心著述。1649 年受瑞典女王克里斯蒂娜之邀去瑞典讲学，因不适应严寒，5 个月后病逝。",
