        "heading": "生平：从伯利恒到耶路撒冷",
        "body": "耶稣出生于罗马帝国犹太行省的伯利恒（圣诞故事）。母亲马利亚因圣灵感孕，养父约瑟是木匠。成长于拿撒勒。约 28-30 岁开始公开传道：从施洗约翰受洗，被圣灵引到旷野受魔鬼试探 40 天；召 12 门徒（彼得、雅各、约翰、安德烈等）；宣讲登山宝训（八福、爱仇敌、金律）；行大量神迹（变水为酒、喂饱五千人、治愈病人、使死人复活）。公元 30 年前后，耶稣骑驴进入耶路撒冷。最后晚餐后，被门徒加略人犹大出卖，被捕，受审，被罗马总督本丢·彼拉多判处钉十字架。死后三天复活，向门徒显现，40 天后升天。"
