    "summary": "印度大乘佛教哲学家。出生于南印度婆罗门家庭。传说曾学隐身术入王宫，后被识破。在说一切有部出家。综合部派佛教与大乘思想，创立中观学派（Madhyamaka），主张「缘起性空」「一切皆空」。",
