        "type": "callout",
        "heading": "最大多数人的最大幸福——功利原则",
        "body": "边沁的功利原则：「最大多数人的最大幸福」是正确与错误的衡量标准。他提出「快乐计算」：每一种快乐的价值 = 强度 × 持续时间 × 确定性 × 邻近性 × 多产性 × 纯粹性 × 范围。他还设计了圆形监狱（panopticon），影响现代监狱设计。",
