    "summary": "英国哲学家、经济学家。父亲是詹姆斯·密尔（边沁弟子）。3 岁学希腊文，8 岁学拉丁文，12 岁学逻辑和经济学，13 岁已读完边沁全部著作。20 岁精神崩溃，休养 2 年。1865 年当选国会议员。1869 年发表《论自由》，捍卫个人自由。",
