    "summary": "德国哲学家。出生于梅斯基希。1909 年入弗莱堡大学，1911 年转学数学、神学、哲学。1923 年到马堡大学任教。1927 年发表《存在与时间》，轰动哲学界。1933 年加入纳粹党，担任弗莱堡大学校长 1 年。1945 年后被禁止教学。",
