    "summary": "法国作家、哲学家。出生于阿尔及利亚蒙多维。父亲是法国移民，母亲是西班牙人。1 岁丧父，由母亲抚养长大。1930 年代加入法国共产党，1934 年退出。1940 年发表《局外人》。1942 年发表《西西弗神话》。1957 年获诺贝尔文学奖。1960 年因车祸去世。",
