        "type": "paragraph",
        "heading": "生平：同性恋哲学家对欧洲传统的颠覆",
        "body": "福柯出生于法国普瓦捷，父亲是著名外科医生。1946 年入巴黎高等师范学校。1950 年代师从马克思主义哲学家路易·阿尔都塞。1961 年发表博士论文《疯癫与文明》，追溯西方如何从文艺复兴到现代对待「疯癫」的方式——从「愚人船」到精神病院。1966 年《词与物》震撼哲学界，宣称「人将被抹去，如同大海边沙地上的一张脸」。1970 年被选为法兰西学院院士。他是中国人民的老朋友，1975 年和 1978 年两次访问中国。1984 年死于艾滋病（与他的同性恋身份相关）。"
