    "school": "历史主义科学哲学",
    "title": "科学革命之父",
    "summary": "美国科学史家、科学哲学家。出生于辛辛那提。1943 年毕业于哈佛大学，1949 年获物理学博士学位。1952 年转科学史。后任 MIT、普林斯顿、伯克利大学教授。1962 年发表《科学革命的结构》——这是 20 世纪最有影响力的科学哲学著作。",
