        "body": "韦伯出生于埃尔福特，父亲是政治律师，母亲是虔诚的新教徒。1882 年入海德堡大学，1886 年在柏林大学获博士学位。1894 年任弗莱堡大学政治经济学教授。1896 年父亲去世，韦伯精神崩溃，住院 4 年半。1904 年起成为《新教伦理与资本主义精神》的开山之作。1919 年任慕尼黑大学教授。1920 年因肺炎去世。他是现代社会学的奠基者之一（与马克思、迪尔凯姆并列），对西方理性化、官僚化（科层制）进行了深刻分析。"
