        "type": "callout",
        "heading": "理性铁笼——现代人的命运",
        "body": "韦伯的核心议题——现代性的命运：① 西方现代化是一个「理性化」过程——工具理性越来越占主导；② 官僚化（科层制）是现代社会的铁律——所有组织都在向科层制发展；③ 「理性铁笼」——人被困在自己制造的理性化机构里；④ 新教伦理曾激励资本主义精神，但资本主义一旦发展起来就摆脱了宗教，追逐纯粹的利益；⑤ 中国未能发展出资本主义，原因是宗教伦理（儒教、道教）不利于资本积累。",
